{"security_risk": "LOW", "summary": "Search extracted handbook strings for ramp and TAL limits", "command": "python - <<'PY'
import re, zlib, pathlib
pdf=pathlib.Path('/app/data/handbook.pdf').read_bytes()

def extract_literal_strings(data:bytes):
    out=[]
    i=0
    while i<len(data):
        if data[i:i+1]==b'(':
            i+=1
            buf=bytearray(); depth=1
            while i<len(data) and depth>0:
                c=data[i]
                if c==0x5c and i+1<len(data):
                    buf.append(data[i+1]); i+=2; continue
                if c==0x28:
                    depth+=1; buf.append(c); i+=1; continue
                if c==0x29:
                    depth-=1
                    if depth==0:
                        i+=1; break
                    buf.append(c); i+=1; continue
                buf.append(c); i+=1
            try:
                out.append(buf.decode('utf-8'))
            except Exception:
                out.append(buf.decode('latin1', errors='ignore'))
            continue
        i+=1
    return out

texts=[]
pos=0
while True:
    s=pdf.find(b'stream', pos)
    if s==-1: break
    dict_start=pdf.rfind(b'<<', 0, s)
    dict_end=pdf.find(b'>>', dict_start, s)
    after=pdf.find(b'\n', s)
    end=pdf.find(b'endstream', after+1)
    if dict_start==-1 or dict_end==-1 or after==-1 or end==-1:
        pos=s+6; continue
    d=pdf[dict_start:dict_end+2]
    data=pdf[after+1:end]
    if b'FlateDecode' in d:
        try:
            dec=zlib.decompress(data)
        except Exception:
            try:
                dec=zlib.decompressobj().decompress(data)
            except Exception:
                pos=end+9; continue
        texts.extend(extract_literal_strings(dec))
    pos=end+9

# Find candidate strings
keywords=['second','C/second','tal','liquidus','Peak','peak','cm/min','cm/minute','conveyor','dwell','TAL']
for kw in keywords:
    hits=[t for t in texts if kw.lower() in t.lower()]
    print('\n===',kw,'hits',len(hits),'===')
    for h in hits[:30]:
        print(h)
PY"}

