{"security_risk": "LOW", "summary": "Enhance handbook text extraction to include hex strings and re-search keywords", "command": "python - <<'PY'
import pathlib, re, zlib, binascii
pdf=pathlib.Path('/app/data/handbook.pdf').read_bytes()

def decode_pdf_string(bs: bytes) -> str:
    # For this handbook, bytes appear to already be mostly Latin-1.
    try:
        return bs.decode('utf-8')
    except Exception:
        return bs.decode('latin1', errors='ignore')

def decode_literal(bs: bytes) -> str:
    out=bytearray(); i=0
    while i<len(bs):
        c=bs[i]
        if c==0x5c:
            i+=1
            if i>=len(bs): break
            c2=bs[i]
            if c2 in b'nrtbf':
                out.append({ord('n'):10,ord('r'):13,ord('t'):9,ord('b'):8,ord('f'):12}[c2]); i+=1
            elif c2 in b'()\\':
                out.append(c2); i+=1
            elif 48<=c2<=55:
                oct_digits=bytes([c2]); i+=1
                for _ in range(2):
                    if i<len(bs) and 48<=bs[i]<=55:
                        oct_digits+=bytes([bs[i]]); i+=1
                    else: break
                out.append(int(oct_digits,8) & 0xFF)
            else:
                out.append(c2); i+=1
        else:
            out.append(c); i+=1
    return decode_pdf_string(bytes(out))

def parse_literal_string(data: bytes, i: int):
    assert data[i:i+1]==b'('
    i+=1; buf=bytearray(); depth=1
    while i<len(data) and depth>0:
        c=data[i]
        if c==0x5c:
            buf.append(c)
            if i+1<len(data):
                buf.append(data[i+1]); i+=2
            else:
                i+=1
            continue
        if c==0x28:
            depth+=1; buf.append(c); i+=1; continue
        if c==0x29:
            depth-=1
            if depth==0:
                i+=1; break
            buf.append(c); i+=1; continue
        buf.append(c); i+=1
    return decode_literal(bytes(buf)), i

def parse_hex_string(data: bytes, i: int):
    assert data[i:i+1]==b'<' and data[i:i+2]!=b'<<'
    i+=1
    buf=bytearray()
    while i<len(data):
        if data[i:i+1]==b'>':
            i+=1; break
        c=data[i:i+1]
        if c in b' \t\r\n\x0c':
            i+=1; continue
        buf.extend(c)
        i+=1
    # If odd number of hex digits, PDF pads with 0
    if len(buf)%2==1:
        buf.extend(b'0')
    try:
        raw=binascii.unhexlify(buf)
    except Exception:
        raw=bytes(buf)
    return decode_pdf_string(raw), i

def parse_array(data: bytes, i: int):
    assert data[i:i+1]==b'['
    i+=1
    parts=[]
    while i<len(data):
        if data[i:i+1]==b']':
            i+=1; break
        if data[i:i+1]==b'(':
            s,i=parse_literal_string(data,i)
            parts.append(s); continue
        if data[i:i+1]==b'<' and data[i:i+2]!=b'<<':
            s,i=parse_hex_string(data,i)
            parts.append(s); continue
        i+=1
    return parts, i

def extract_text_from_content(data: bytes) -> str:
    out=[]; operands=[]; i=0
    while i<len(data):
        c=data[i:i+1]
        if c in b' \t\r\n\x0c\x00':
            i+=1; continue
        if c==b'%':
            j=data.find(b'\n',i)
            i=(j+1 if j!=-1 else len(data)); continue
        if c==b'(':
            s,i=parse_literal_string(data,i)
            operands.append(s); continue
        if c==b'<' and data[i:i+2]!=b'<<':
            s,i=parse_hex_string(data,i)
            operands.append(s); continue
        if c==b'[':
            arr,i=parse_array(data,i)
            operands.append(arr); continue
        if 65<=data[i]<=90 or 97<=data[i]<=122:
            j=i
            while j<len(data) and (65<=data[j]<=90 or 97<=data[j]<=122 or data[j] in b'*'):
                j+=1
            op=data[i:j].decode('latin1')
            if op=='Tj':
                if operands and isinstance(operands[-1], str):
                    out.append(operands[-1])
                operands.clear()
            elif op=='TJ':
                if operands and isinstance(operands[-1], list):
                    out.append(''.join(operands[-1]))
                operands.clear()
            elif op in ('Td','TD','T*'):
                out.append('\n'); operands.clear()
            else:
                operands.clear()
            i=j; continue
        i+=1
    txt=' '.join(out)
    txt=re.sub(r'[ \t\r\f\v]+',' ',txt)
    txt=re.sub(r'\n+','\n',txt)
    return txt

texts=[]
pos=0
while True:
    s=pdf.find(b'stream',pos)
    if s==-1: break
    ds=pdf.rfind(b'<<',0,s)
    de=pdf.find(b'>>',ds,s)
    nl=pdf.find(b'\n',s)
    es=pdf.find(b'endstream',nl+1)
    if ds==-1 or de==-1 or nl==-1 or es==-1:
        pos=s+6; continue
    d=pdf[ds:de+2]
    if b'FlateDecode' not in d:
        pos=es+9; continue
    data=pdf[nl+1:es]
    try:
        dec=zlib.decompress(data)
    except Exception:
        dec=zlib.decompressobj().decompress(data)
    texts.append(extract_text_from_content(dec))
    pos=es+9

full='\n'.join(texts)
full=re.sub(r'\s+',' ',full)
print('chars',len(full))

# search for terms
terms=['liquidus','wetting time','time above','above liquidus','TAL','peak','maximum','reflow peak','peak temperature','°C','C']
for t in terms:
    print(t, len(re.findall(t, full, flags=re.IGNORECASE)))

for kw in ['wetting','30-60','time','liquid','peak','maximum','melting point','above its melting point','temperature generally','peak temp','reflow section']:
    m=re.search(rf'.{{0,200}}{re.escape(kw)}.{{0,260}}', full, flags=re.IGNORECASE)
    print('\n---',kw,'---')
    if m:
        print(m.group(0))
    else:
        print('not found')
