    while i<len(bs):
        c=bs[i]
        if c==0x5c:
            i+=1
            if i>=len(bs): break
            c2=bs[i]
            if c2 in b'nrtbf':
                out.append({ord('n'):10,ord('r'):13,ord('t'):9,ord('b'):8,ord('f'):12}[c2]); i+=1
