                        oct_digits+=bytes([bs[i]]); i+=1
                    else: break
                out.append(int(oct_digits,8) & 0xFF)
            else:
                out.append(c2); i+=1
        else:
            out.append(c); i+=1
    return decode_pdf_string(bytes(out))

