def extract_text_from_content(data: bytes) -> str:
    out=[]
    operands=[]
    i=0
    while i<len(data):
        c=data[i:i+1]
        if c in b' \t\r\n\x0c\x00':
            i+=1; continue
        if c==b'%':
            j=data.find(b'\n', i)
            i=(j+1 if j!=-1 else len(data));
            continue
        if c==b'(':
            s,i=parse_lit(data,i); operands.append(s); continue
        if c==b'<' and data[i:i+2]!=b'<<':
            s,i=parse_hex(data,i); operands.append(s); continue
        if c==b'[':
            arr,i=parse_arr(data,i); operands.append(arr); continue
        if 65<=data[i]<=90 or 97<=data[i]<=122:
            j=i
            while j<len(data) and (65<=data[j]<=90 or 97<=data[j]<=122 or data[j] in b'*'):
                j+=1
            op=data[i:j].decode('latin1')
            if op=='Tj' and operands and isinstance(operands[-1], str):
                out.append(operands[-1])
            elif op=='TJ' and operands and isinstance(operands[-1], list):
                out.append(''.join(operands[-1]))
            elif op in ('Td','TD','T*'):
                out.append('\n')
            operands.clear();
            i=j
            continue
        i+=1
    txt=' '.join(out)
    txt=re.sub(r'[ \t\r\f\v]+',' ',txt)
    txt=re.sub(r'\n+','\n',txt)
    return txt

pdf=(data_dir/'handbook.pdf').read_bytes()
texts=[]
pos=0
while True:
    s=pdf.find(b'stream', pos)
    if s==-1:
        break
    ds=pdf.rfind(b'<<', 0, s)
    de=pdf.find(b'>>', ds, s)
    nl=pdf.find(b'\n', s)
    es=pdf.find(b'endstream', nl+1)
    if ds==-1 or de==-1 or nl==-1 or es==-1:
        pos=s+6
        continue
    d=pdf[ds:de+2]
    if b'FlateDecode' not in d:
        pos=es+9
        continue
    comp=pdf[nl+1:es]
    try:
        dec=zlib.decompress(comp)
    except Exception:
        dec=zlib.decompressobj().decompress(comp)
    texts.append(extract_text_from_content(dec))
    pos=es+9

handbook_text=re.sub(r'\s+',' ', ' '.join(texts)).strip()

# --- Extract handbook parameters (do not guess) ---
preheat_m=re.search(r'preheat[^.]{0,220}?between\s+(\d+)\s*\u00b0C\s*to\s*(\d+)\s*\u00b0', handbook_text, flags=re.IGNORECASE)
preheat_low=float(preheat_m.group(1)) if preheat_m else None
preheat_high=float(preheat_m.group(2)) if preheat_m else None

ramp_m=re.search(r'rate of rise[^.]{0,140}?less than\s*(\d+(?:\.\d+)?)\s*[^\w]{0,6}C/second', handbook_text, flags=re.IGNORECASE)
ramp_limit=float(ramp_m.group(1)) if ramp_m else None

peak_margin_m=re.search(r'must be ex\s*-\s*ceeded by approximately\s*(\d+(?:\.\d+)?)\s*\u00b0C', handbook_text, flags=re.IGNORECASE)
peak_margin=float(peak_margin_m.group(1)) if peak_margin_m else None

wet_m=re.search(r'wetting time\W+is\W+normally\s*(\d+(?:\.\d+)?)\s*to\s*(\d+(?:\.\d+)?)\s*seconds', handbook_text, flags=re.IGNORECASE)
wet_min=float(wet_m.group(1)) if wet_m else None
wet_max=float(wet_m.group(2)) if wet_m else None

# --- Load CSVs ---
mes=pd.read_csv(data_dir/'mes_log.csv')
th=pd.read_csv(data_dir/'thermocouples.csv')
defects=pd.read_csv(data_dir/'test_defects.csv')
for df in (mes,th,defects):
    df['run_id']=df['run_id'].astype(str)

mes_liq=mes.set_index('run_id')['solder_liquidus_c'].to_dict()

# --- numeric helpers ---

def max_ramp_in_band(df_tc, low, high):
    if df_tc.empty or low is None or high is None:
        return None
    d=df_tc.sort_values('time_s')
    t=d['time_s'].to_numpy(float)
    y=d['temp_c'].to_numpy(float)
    m=None
    for i in range(len(t)-1):
        if t[i+1] <= t[i]:
            continue
        seg_min=min(y[i],y[i+1]); seg_max=max(y[i],y[i+1])
        if seg_max < low or seg_min > high:
            continue
        slope=(y[i+1]-y[i])/(t[i+1]-t[i])
        if slope <= 0:
            continue
        if m is None or slope>m:
            m=float(slope)
    return m

def time_above(df_tc, thr):
    if df_tc.empty or thr is None or (isinstance(thr,float) and math.isnan(thr)):
        return None
    d=df_tc.sort_values('time_s')
    t=d['time_s'].to_numpy(float)
    y=d['temp_c'].to_numpy(float)
    total=0.0
    for i in range(len(t)-1):
        t0,t1=t[i],t[i+1]
        if t1<=t0:
            continue
        y0,y1=y[i],y[i+1]
        if y0>=thr and y1>=thr:
            total += (t1-t0)
        elif y0<thr and y1<thr:
            continue
        else:
            if y1==y0:
                continue
            tcross=t0 + (thr-y0)*(t1-t0)/(y1-y0)
            if y0<thr and y1>thr:
                total += max(0.0, t1-tcross)
            elif y0>thr and y1<thr:
                total += max(0.0, tcross-t0)
    return float(total)

def peak(df_tc):
    return None if df_tc.empty else float(df_tc['temp_c'].max())

# --- Q1 ---
q1_max=OrderedDict(); violating=[]
for run_id in sorted(mes['run_id'].unique()):
    run_tc=th[th.run_id==run_id]
    worst_tc=None; worst=None
    for tc_id, df_tc in run_tc.groupby('tc_id'):
        r=max_ramp_in_band(df_tc, preheat_low, preheat_high)
        if r is None:
            continue
        if worst is None or r>worst:
            worst=r; worst_tc=str(tc_id)
    q1_max[run_id]={
        'tc_id': worst_tc,
        'max_preheat_ramp_c_per_s': (round(worst,2) if worst is not None else None)
    }
    if ramp_limit is not None and worst is not None and worst>ramp_limit:
        violating.append(run_id)

q1={
  'ramp_rate_limit_c_per_s': (round(ramp_limit,2) if ramp_limit is not None else None),
  'violating_runs': sorted(violating),
  'max_ramp_by_run': q1_max
}
(out_dir/'q01.json').write_text(json.dumps(q1, indent=2))

# --- Q2 ---
q2=[]
for run_id in sorted(mes['run_id'].unique()):
    liq=mes_liq.get(run_id)
    liq=None if liq is None or (isinstance(liq,float) and math.isnan(liq)) else float(liq)
    run_tc=th[th.run_id==run_id]
    if run_tc.empty:
        q2.append({
            'run_id': run_id,
            'tc_id': None,
            'tal_s': None,
            'required_min_tal_s': (round(wet_min,2) if wet_min is not None else None),
            'required_max_tal_s': (round(wet_max,2) if wet_max is not None else None),
            'status': 'non-compliant'
        })
        continue
    for tc_id, df_tc in run_tc.groupby('tc_id'):
        tal=time_above(df_tc, liq)
        status='non-compliant'
        if tal is not None and wet_min is not None and wet_max is not None and wet_min<=tal<=wet_max:
            status='compliant'
        q2.append({
            'run_id': run_id,
            'tc_id': str(tc_id),
            'tal_s': (round(tal,2) if tal is not None else None),
            'required_min_tal_s': (round(wet_min,2) if wet_min is not None else None),
            'required_max_tal_s': (round(wet_max,2) if wet_max is not None else None),
            'status': status
        })
q2.sort(key=lambda r: (r['run_id'], '' if r['tc_id'] is None else r['tc_id']))
(out_dir/'q02.json').write_text(json.dumps(q2, indent=2))

# --- Q3 ---
q3_min=OrderedDict(); failing=[]
for run_id in sorted(mes['run_id'].unique()):
    liq=mes_liq.get(run_id)
    liq=None if liq is None or (isinstance(liq,float) and math.isnan(liq)) else float(liq)
    required=(liq+peak_margin) if (liq is not None and peak_margin is not None) else None

    run_tc=th[th.run_id==run_id]
    if run_tc.empty:
        failing.append(run_id)
        q3_min[run_id]={
            'tc_id': None,
            'peak_temp_c': None,
            'required_min_peak_c': (round(required,2) if required is not None else None)
        }
        continue

    worst_tc=None; worst=None
    for tc_id, df_tc in run_tc.groupby('tc_id'):
        p=peak(df_tc)
        if p is None:
            continue
        if worst is None or p<worst:
            worst=p; worst_tc=str(tc_id)

    q3_min[run_id]={
        'tc_id': worst_tc,
        'peak_temp_c': (round(worst,2) if worst is not None else None),
        'required_min_peak_c': (round(required,2) if required is not None else None)
    }

    if worst is None or required is None or worst<required:
        failing.append(run_id)

q3={
  'failing_runs': sorted(failing),
  'min_peak_by_run': q3_min
}
(out_dir/'q03.json').write_text(json.dumps(q3, indent=2))

# --- Q4 ---
q4=[]
for _, row in mes.sort_values('run_id').iterrows():
    run_id=row['run_id']
    bpm=row.get('boards_per_min')
    L=row.get('board_length_cm')
    lf=row.get('loading_factor')
    actual=row.get('conveyor_speed_cm_min')

    req=None
    if pd.notna(bpm) and pd.notna(L) and pd.notna(lf) and float(lf)!=0.0:
        req=float(bpm)*float(L)/float(lf)
    meets=bool(req is not None and pd.notna(actual) and float(actual)>=req)

    q4.append({
        'run_id': run_id,
        'required_min_speed_cm_min': (round(req,2) if req is not None else None),
        'actual_speed_cm_min': (round(float(actual),2) if pd.notna(actual) else None),
        'meets': meets
    })
(out_dir/'q04.json').write_text(json.dumps(q4, indent=2))

# --- Q5 ---
# Worst-case TAL for each run (min across TCs)
run_min_tal={}
for run_id in sorted(mes['run_id'].unique()):
    liq=mes_liq.get(run_id)
    liq=None if liq is None or (isinstance(liq,float) and math.isnan(liq)) else float(liq)
    run_tc=th[th.run_id==run_id]
    if run_tc.empty or liq is None:
        run_min_tal[run_id]=None
        continue
    vals=[time_above(df, liq) for _,df in run_tc.groupby('tc_id')]
    vals=[v for v in vals if v is not None]
    run_min_tal[run_id]=min(vals) if vals else None

run_max_ramp={rid: (None if v['max_preheat_ramp_c_per_s'] is None else float(v['max_preheat_ramp_c_per_s'])) for rid,v in q1_max.items()}
run_min_peak={rid: (None if v['peak_temp_c'] is None else float(v['peak_temp_c'])) for rid,v in q3_min.items()}
q4_by_run={r['run_id']: r for r in q4}

summary=defects[defects['inspection_stage'].astype(str).str.upper()=='SUMMARY'].copy()
for c in ['fp_yield_pct','units_scrap','units_rework']:
    if c in summary.columns:
        summary[c]=pd.to_numeric(summary[c], errors='coerce')
summary_by_run=summary.groupby('run_id').agg({'fp_yield_pct':'max','units_scrap':'max','units_rework':'max'}).to_dict('index')
mes_idx=mes.set_index('run_id')


def is_compliant(rid: str) -> bool:
    mr=run_max_ramp.get(rid)
    if mr is None or ramp_limit is None or mr>ramp_limit:
        return False
    mt=run_min_tal.get(rid)
    if mt is None or wet_min is None or wet_max is None or not (wet_min<=mt<=wet_max):
        return False
    liq=mes_liq.get(rid)
    liq=None if liq is None or (isinstance(liq,float) and math.isnan(liq)) else float(liq)
    if liq is None or peak_margin is None:
        return False
    req=liq+peak_margin
    mp=run_min_peak.get(rid)
    if mp is None or mp<req:
        return False
    if not q4_by_run.get(rid, {}).get('meets', False):
        return False
    return True

families=sorted(mes['board_family'].astype(str).unique())
q5=[]
for fam in families:
    runs=sorted(set(mes[mes['board_family'].astype(str)==fam]['run_id'].astype(str)))

    def key(rid: str):
        s=summary_by_run.get(rid, {})
        fp=s.get('fp_yield_pct'); scrap=s.get('units_scrap'); rework=s.get('units_rework')
        bpm=mes_idx.loc[rid]['boards_per_min'] if rid in mes_idx.index else None
        downtime=mes_idx.loc[rid]['downtime_s'] if rid in mes_idx.index else None
        comp=is_compliant(rid)
        return (
            0 if comp else 1,
            -(float(fp) if fp is not None and not math.isnan(fp) else -1e9),
            float(scrap) if scrap is not None and not math.isnan(scrap) else 1e9,
            float(rework) if rework is not None and not math.isnan(rework) else 1e9,
            -(float(bpm) if bpm is not None and not (isinstance(bpm,float) and math.isnan(bpm)) else -1e9),
            float(downtime) if downtime is not None and not (isinstance(downtime,float) and math.isnan(downtime)) else 1e9,
            rid
        )

    ranked=sorted(runs, key=key)
    best=ranked[0] if ranked else None

    q5.append({
        'board_family': fam,
        'best_run_id': best,
        'runner_up_run_ids': sorted([r for r in runs if r!=best])
    })

q5.sort(key=lambda r: r['board_family'])
(out_dir/'q05.json').write_text(json.dumps(q5, indent=2))

print('Extracted from handbook:', {
