        q2.append({
            'run_id': run_id,
            'tc_id': str(tc_id),
            'tal_s': (round(tal,2) if tal is not None else None),
            'required_min_tal_s': (round(wet_min,2) if wet_min is not None else None),
            'required_max_tal_s': (round(wet_max,2) if wet_max is not None else None),
            'status': status
        })
q2.sort(key=lambda r: (r['run_id'], '' if r['tc_id'] is None else r['tc_id']))
(out_dir/'q02.json').write_text(json.dumps(q2, indent=2))

# --- Q3 ---
q3_min=OrderedDict(); failing=[]
for run_id in sorted(mes['run_id'].unique()):
    liq=mes_liq.get(run_id)
    liq=None if liq is None or (isinstance(liq,float) and math.isnan(liq)) else float(liq)
    required=(liq+peak_margin) if (liq is not None and peak_margin is not None) else None

    run_tc=th[th.run_id==run_id]
    if run_tc.empty:
        failing.append(run_id)
        q3_min[run_id]={
            'tc_id': None,
            'peak_temp_c': None,
            'required_min_peak_c': (round(required,2) if required is not None else None)
        }
        continue

    worst_tc=None; worst=None
    for tc_id, df_tc in run_tc.groupby('tc_id'):
        p=peak(df_tc)
        if p is None:
            continue
        if worst is None or p<worst:
            worst=p; worst_tc=str(tc_id)

    q3_min[run_id]={
        'tc_id': worst_tc,
        'peak_temp_c': (round(worst,2) if worst is not None else None),
        'required_min_peak_c': (round(required,2) if required is not None else None)
    }

    if worst is None or required is None or worst<required:
