            float(rework) if rework is not None and not math.isnan(rework) else 1e9,
            -(float(bpm) if bpm is not None and not (isinstance(bpm,float) and math.isnan(bpm)) else -1e9),
            float(downtime) if downtime is not None and not (isinstance(downtime,float) and math.isnan(downtime)) else 1e9,
            rid
        )

    ranked=sorted(runs, key=key)
    best=ranked[0] if ranked else None

    q5.append({
        'board_family': fam,
        'best_run_id': best,
        'runner_up_run_ids': sorted([r for r in runs if r!=best])
