import json, math, re, pathlib, zlib, binascii
from collections import OrderedDict
import pandas as pd

data_dir=pathlib.Path('/app/data')
out_dir=pathlib.Path('/app/output')
out_dir.mkdir(parents=True, exist_ok=True)

# --- PDF text extraction (content streams) ---

def decode_pdf_string(bs: bytes) -> str:
    try:
        return bs.decode('utf-8')
    except Exception:
        return bs.decode('latin1', errors='ignore')

def decode_literal(bs: bytes) -> str:
    out=bytearray(); i=0
    while i<len(bs):
        c=bs[i]
        if c==0x5c:
            i+=1
            if i>=len(bs):
                break
            c2=bs[i]
            if c2 in b'nrtbf':
                out.append({ord('n'):10,ord('r'):13,ord('t'):9,ord('b'):8,ord('f'):12}[c2]); i+=1
            elif c2 in b'()\\':
                out.append(c2); i+=1
            elif 48<=c2<=55:
                octd=bytes([c2]); i+=1
                for _ in range(2):
                    if i<len(bs) and 48<=bs[i]<=55:
                        octd+=bytes([bs[i]]); i+=1
                    else:
                        break
                out.append(int(octd,8) & 0xFF)
            else:
                out.append(c2); i+=1
        else:
            out.append(c); i+=1
    return decode_pdf_string(bytes(out))

def parse_lit(data: bytes, i: int):
    i+=1
    buf=bytearray(); depth=1
    while i<len(data) and depth>0:
        c=data[i]
        if c==0x5c:
            buf.append(c)
            if i+1<len(data):
                buf.append(data[i+1]); i+=2
            else:
                i+=1
            continue
        if c==0x28:
            depth+=1; buf.append(c); i+=1; continue
        if c==0x29:
            depth-=1
            if depth==0:
                i+=1; break
            buf.append(c); i+=1; continue
        buf.append(c); i+=1
    return decode_literal(bytes(buf)), i

def parse_hex(data: bytes, i: int):
    i+=1
    buf=bytearray()
    while i<len(data):
        if data[i:i+1]==b'>':
            i+=1; break
        if data[i:i+1] in b' \t\r\n\x0c':
            i+=1; continue
        buf.append(data[i]); i+=1
    if len(buf)%2==1:
        buf.append(ord('0'))
    try:
        raw=binascii.unhexlify(buf)
    except Exception:
        raw=bytes(buf)
    return decode_pdf_string(raw), i

def parse_arr(data: bytes, i: int):
    i+=1
    parts=[]
    while i<len(data):
        if data[i:i+1]==b']':
            i+=1; break
        if data[i:i+1]==b'(':
            s,i=parse_lit(data,i); parts.append(s); continue
        if data[i:i+1]==b'<' and data[i:i+2]!=b'<<':
            s,i=parse_hex(data,i); parts.append(s); continue
        i+=1
    return parts, i

def extract_text_from_content(data: bytes) -> str:
    out=[]
    operands=[]
    i=0
    while i<len(data):
        c=data[i:i+1]
        if c in b' \t\r\n\x0c\x00':
            i+=1; continue
        if c==b'%':
            j=data.find(b'\n', i)
            i=(j+1 if j!=-1 else len(data));
            continue
        if c==b'(':
            s,i=parse_lit(data,i); operands.append(s); continue
        if c==b'<' and data[i:i+2]!=b'<<':
            s,i=parse_hex(data,i); operands.append(s); continue
        if c==b'[':
            arr,i=parse_arr(data,i); operands.append(arr); continue
        if 65<=data[i]<=90 or 97<=data[i]<=122:
            j=i
            while j<len(data) and (65<=data[j]<=90 or 97<=data[j]<=122 or data[j] in b'*'):
                j+=1
            op=data[i:j].decode('latin1')
            if op=='Tj' and operands and isinstance(operands[-1], str):
                out.append(operands[-1])
            elif op=='TJ' and operands and isinstance(operands[-1], list):
                out.append(''.join(operands[-1]))
            elif op in ('Td','TD','T*'):
                out.append('\n')
            operands.clear();
            i=j
            continue
        i+=1
    txt=' '.join(out)
    txt=re.sub(r'[ \t\r\f\v]+',' ',txt)
    txt=re.sub(r'\n+','\n',txt)
    return txt

pdf=(data_dir/'handbook.pdf').read_bytes()
texts=[]
pos=0
while True:
    s=pdf.find(b'stream', pos)
    if s==-1:
        break
    ds=pdf.rfind(b'<<', 0, s)
