    if liq is None or peak_margin is None:
        return False
    req=liq+peak_margin
    mp=run_min_peak.get(rid)
    if mp is None or mp<req:
        return False
    if not q4_by_run.get(rid, {}).get('meets', False):
        return False
    return True

families=sorted(mes['board_family'].astype(str).unique())
q5=[]
for fam in families:
    runs=sorted(set(mes[mes['board_family'].astype(str)==fam]['run_id'].astype(str)))

    def key(rid: str):
        s=summary_by_run.get(rid, {})
        fp=s.get('fp_yield_pct'); scrap=s.get('units_scrap'); rework=s.get('units_rework')
        bpm=mes_idx.loc[rid]['boards_per_min'] if rid in mes_idx.index else None
        downtime=mes_idx.loc[rid]['downtime_s'] if rid in mes_idx.index else None
