import pathlib, re, zlib
pdf=pathlib.Path('/app/data/handbook.pdf').read_bytes()

def decode_pdf_string(bs: bytes) -> str:
    out=bytearray(); i=0
    while i<len(bs):
        c=bs[i]
        if c==0x5c:  # backslash
            i+=1
            if i>=len(bs): break
            c2=bs[i]
            if c2 in b'nrtbf':
                out.append({ord('n'):10,ord('r'):13,ord('t'):9,ord('b'):8,ord('f'):12}[c2])
                i+=1
            elif c2 in b'()\\':
                out.append(c2); i+=1
            elif 48<=c2<=55:  # octal
                oct_digits=bytes([c2])
                i+=1
                for _ in range(2):
                    if i<len(bs) and 48<=bs[i]<=55:
                        oct_digits+=bytes([bs[i]]); i+=1
                    else:
                        break
                out.append(int(oct_digits,8) & 0xFF)
            else:
                out.append(c2); i+=1
        else:
            out.append(c); i+=1
    try:
        return out.decode('utf-8')
    except Exception:
        return out.decode('latin1', errors='ignore')

def parse_string(data: bytes, i: int):
    assert data[i:i+1]==b'('
    i+=1
    buf=bytearray(); depth=1
    while i<len(data) and depth>0:
        c=data[i]
        if c==0x5c:  # escape
            buf.append(c)
            if i+1<len(data):
                buf.append(data[i+1])
                i+=2
            else:
                i+=1
            continue
        if c==0x28:
            depth+=1; buf.append(c); i+=1; continue
        if c==0x29:
            depth-=1
            if depth==0:
                i+=1
                break
            buf.append(c); i+=1; continue
        buf.append(c); i+=1
    return decode_pdf_string(bytes(buf)), i

def parse_array(data: bytes, i: int):
    assert data[i:i+1]==b'['
    i+=1
    strings=[]
    while i<len(data):
        c=data[i:i+1]
        if c==b']':
            i+=1
            break
        if c==b'(':
            s,i=parse_string(data,i)
            strings.append(s)
            continue
        # skip other tokens (numbers, names, etc.)
        i+=1
    return strings, i

def extract_text_from_content(data: bytes) -> str:
    out=[]
    operands=[]
    i=0
    while i<len(data):
        c=data[i:i+1]
        if c in b' \t\r\n\x0c\x00':
            i+=1; continue
        if c==b'%':
            # comment to end of line
            j=data.find(b'\n', i)
            if j==-1: break
            i=j+1
            continue
        if c==b'(':
            s,i=parse_string(data,i)
            operands.append(s)
            continue
        if c==b'[':
            arr,i=parse_array(data,i)
            operands.append(arr)
            continue
        if 65<=data[i]<=90 or 97<=data[i]<=122:  # operator/keyword
            j=i
            while j<len(data) and (65<=data[j]<=90 or 97<=data[j]<=122 or data[j] in b'*'):
                j+=1
            op=data[i:j].decode('latin1')
            if op=='Tj':
                if operands and isinstance(operands[-1], str):
                    out.append(operands[-1])
                operands.clear()
            elif op=='TJ':
                if operands and isinstance(operands[-1], list):
                    out.append(''.join(operands[-1]))
                operands.clear()
            elif op in ('Td','TD','T*'):
                out.append('\n')
                operands.clear()
            else:
                # other operator
                operands.clear()
            i=j
            continue
        # skip any other token: ***REDACTED***, /Name, <hex>, etc.
        i+=1
    # normalize whitespace
    txt=' '.join([t for t in out if t is not None])
    txt=re.sub(r'[ \t\r\f\v]+',' ',txt)
    txt=re.sub(r'\n+','\n',txt)
    return txt

# decompress Flate streams and extract text operators
texts=[]
pos=0
while True:
    s=pdf.find(b'stream', pos)
    if s==-1: break
    dict_start=pdf.rfind(b'<<', 0, s)
    dict_end=pdf.find(b'>>', dict_start, s)
    after=pdf.find(b'\n', s)
    end=pdf.find(b'endstream', after+1)
    if dict_start==-1 or dict_end==-1 or after==-1 or end==-1:
        pos=s+6; continue
    d=pdf[dict_start:dict_end+2]
    data=pdf[after+1:end]
    if b'FlateDecode' in d:
        try:
            dec=zlib.decompress(data)
        except Exception:
            try:
                dec=zlib.decompressobj().decompress(data)
            except Exception:
                pos=end+9; continue
        texts.append(extract_text_from_content(dec))
    pos=end+9

full='\n'.join(texts)
full=re.sub(r'\s+',' ',full)
print('extracted chars', len(full))

# print snippets around key terms
for kw in ['preheat','rate of rise','C/second','liquidus','time above','TAL','peak','conveyor','LINE SPEED','Dwell','cm/min']:
    m=re.search(rf'.{{0,200}}{kw}.{{0,260}}', full, flags=re.IGNORECASE)
    print('\n---',kw,'---')
    if m:
        print(m.group(0))
    else:
        print('not found')

